WITH sales_by_hour AS ( SELECT t.t_hour, SUM(ss.ss_net_paid) AS total_sales, SUM(ss.ss_net_profit) AS total_profit FROM store_sales ss JOIN time_dim t ON ss.ss_sold_time_sk = t.t_time_sk GROUP BY t.t_hour ), returns_by_hour AS ( SELECT t.t_hour, SUM(cr.cr_return_amount) AS total_returns, SUM(cr.cr_net_loss) AS total_return_loss FROM catalog_returns cr JOIN time_dim t ON cr.cr_returned_time_sk = t.t_time_sk GROUP BY t.t_hour ) SELECT s.t_hour, s.total_sales, r.total_returns, s.total_sales - COALESCE(r.total_returns, 0) AS net_sales_minus_returns, SUM(s.total_sales - COALESCE(r.total_returns, 0)) OVER ( ORDER BY s.t_hour ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cumulative_net, CASE WHEN s.total_sales - COALESCE(r.total_returns, 0) < 0 THEN 'Loss' ELSE 'Profit' END AS hour_status, RANK() OVER (ORDER BY s.total_sales - COALESCE(r.total_returns, 0) DESC) AS profit_rank FROM sales_by_hour s LEFT JOIN returns_by_hour r ON s.t_hour = r.t_hour ORDER BY s.t_hour
